                putchar('\n');
            }
            x = 0;
            seen = 0;
            if (c < 0) break;
        }
    }
    return 0;
}

#include <stdint.h>

/* Expand a bit mask to 0x00/0xFF byte lanes: one bit of the input per byte
 * of the output.  Written by hand as a bit deposit and a multiply by 0xFF. */
uint64_t byte_mask8(uint8_t m)
{
    uint64_t r = 0;

    for (unsigned i = 0; i < 8; ++i)
        if ((m >> i) & 1)
            r |= 0xFFull << (8 * i);

    return r;
}

