/* Run ends: a set bit whose right neighbour is clear.  The mirror of
 * starts8, and `x & ~(x >> 1)` by hand. */
uint64_t ends8(uint8_t m)
{
    uint64_t x = m;

    return x & ~(x >> 1);
}

