 * needed to represent x in two's complement.
 *
 * howManyBits(12) is 5, howManyBits(298) is 10, howManyBits(-5) is 4, and both
 * howManyBits(0) and howManyBits(-1) are 1. */
uint32_t how_many_bits_i32(uint32_t x)
{
    int32_t v = (int32_t)x;
    uint32_t n = 1;

    if (v < 0) v = ~v;
    while (v) { v >>= 1; n += 1; }
    return n;
}

